// Normaliser le message brut reçu du groupe WhatsApp
const item = $input.first().json.body || $input.first().json;

const rawMessage = item.text || item.body || item.message?.conversation || '';
const senderJid = item.sender || item.from || item.key?.remoteJid || '';
const senderPhone = senderJid.replace(/\D/g, '');

// Filtrer les messages trop courts ou non pertinents
if (!rawMessage || rawMessage.length < 25) {
  return [];
}

return [{
  json: {
    rawMessage,
    senderPhone: senderPhone || null,
    receivedAt: new Date().toISOString()
  }
}];

