// Mappage des champs extraits pour la table 'locaux' Supabase
const rawAi = $input.first().json;
let parsed = {};
try {
  const content = rawAi.choices?.[0]?.message?.content || '{}';
  parsed = JSON.parse(content);
} catch (e) {
  parsed = {};
}

const prev = $('Validation & Nettoyage').first().json;

return [{
  json: {
    message_initial: prev.rawMessage,
    commune: parsed.commune || 'Abidjan',
    quartier: parsed.quartier || null,
    type_de_bien: parsed.type_de_bien || 'Appartement',
    type_offre: parsed.type_offre || 'location',
    prix: parsed.prix ? String(parsed.prix) : 'Prix sur demande',
    telephone_bien: parsed.telephone_bien || prev.senderPhone || null,
    disponible: 'oui',
    status: 'active',
    is_duplicate: false,
    date_publication: prev.receivedAt
  }
}];
